"""Summarize completed source-presentation pilot with historical matched baseline."""
import pathlib,json,hashlib,datetime,collections
p=pathlib.Path(__file__).resolve().parent
def meta(f):return {'path':str(f),'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'bytes':f.stat().st_size}
resources=json.loads((p/'resources.json').read_text());final=p/'run/result.json';status=json.loads(final.read_text())['status'] if final.exists() else ('timeout' if resources['exit_code']==124 else 'process-failure');rounds=[]
for f in sorted((p/'run').glob('round-*.json')):
 x=json.loads(f.read_text());original={tuple(t['indices']) for row in x['original_target_rows'] for t in row};joint=collections.Counter((i[0],i[9]) for i in original)
 rounds.append({'round':x['round'],'requested':len(x['requested']),'cumulative_requested':len(x['attempted_exact_points']),'frontier':len(x['frontier']),'rules':x['rule_count'],'zero_first_rules':x['zero_first_rule_count'],'processed_actual_derivatives':len(x['derivative_rows']),'original_output_row_terms':list(map(len,x['original_target_rows'])),'original_output_distinct_leaves':len(original),'positive_energy_leaves':sum(i[6]>0 for i in original),'joint_cut_surface_distribution':[{'cut':c,'upper_surface':h,'count':n}for(c,h),n in sorted(joint.items())],'conditions':len(x['conditions_encountered']),'seconds':x['seconds'],'checkpoint':meta(f)})
baseline_file=pathlib.Path('reports/validation/2026-10-10-occupation-order-experiment/pilot-three-arm-summary.json');baseline=json.loads(baseline_file.read_text())['arms']['baseline']
out={'recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'scope':'Independent polynomial singleton C1 shell-Ward source pilot; no reciprocal-energy admission, numerical evaluation, oracle data or historical rule import','status':status,'closure_proved':status=='closed','runtime_scope':'opt-level0 standalone wrapper; release dependencies; compilation excluded; historical timings not a controlled machine-load benchmark','resources':resources,'source':meta(p.parent/'native-active-pilot/pilot.rs'),'source_delta':meta(p/'source-binding.json'),'settings':json.loads((p/'run/configuration.json').read_text()),'completed_rounds':rounds,'final_result':meta(final) if final.exists()else None,'interrupted_round_incomplete':resources['exit_code']==124,'historical_matched_baseline':{'summary':meta(baseline_file),'status':baseline['status'],'resources':baseline['resources'],'completed_rounds':baseline['completed_rounds']}}
(p/'summary.json').write_text(json.dumps(out,indent=2)+'\n');print(status,[(r['frontier'],r['rules'])for r in rounds])
